// hands tie for best, all of them are returned.
func BestHand(hands []string) ([]string, error) {
	if len(hands) == 0 {
		return nil, errors.New("no hands given")
	}

	scores := make([]handScore, len(hands))
	for i, hand := range hands {
		cards, err := parseHand(hand)
		if err != nil {
			return nil, err
		}
		scores[i] = scoreHand(cards)
	}

	best := make([]string, 0, 1)
	var bestScore handScore
	for i, hand := range hands {
		if len(best) == 0 {
			best = append(best, hand)
			bestScore = scores[i]
			continue
		}
		switch scores[i].compare(bestScore) {
		case 1:
			best = []string{hand}
			bestScore = scores[i]
		case 0:
			best = append(best, hand)
		}
	}

	return best, nil
}
